<section class="survey-question-card" data-survey-question>
    <div class="survey-question-heading"><strong data-question-number>Question {{ is_numeric($index)?$index+1:'' }}</strong><div class="actions"><button type="button" class="secondary small" data-question-up aria-label="Move question up">↑</button><button type="button" class="secondary small" data-question-down aria-label="Move question down">↓</button><button type="button" class="danger small" data-question-remove>Remove</button></div></div>
    <input type="hidden" name="questions[{{ $index }}][id]" value="{{ $question['id']??'' }}">
    <div class="field"><label for="question-{{ $index }}-label">Question text</label><input id="question-{{ $index }}-label" name="questions[{{ $index }}][label]" value="{{ $question['label']??'' }}" maxlength="255" required></div>
    <div class="content-choice-grid"><div class="field"><label for="question-{{ $index }}-type">Answer type</label><select id="question-{{ $index }}-type" name="questions[{{ $index }}][type]" data-question-type>@foreach(\App\Services\SurveyForms::TYPES as $key=>$label)<option value="{{ $key }}" @selected(($question['type']??'short_text')===$key)>{{ $label }}</option>@endforeach</select></div><div class="field"><label for="question-{{ $index }}-required">Required answer</label><select id="question-{{ $index }}-required" name="questions[{{ $index }}][required]"><option value="0" @selected(empty($question['required']))>Optional</option><option value="1" @selected(!empty($question['required']))>Required</option></select></div></div>
    <div class="field"><label for="question-{{ $index }}-help">Help text (optional)</label><input id="question-{{ $index }}-help" name="questions[{{ $index }}][help]" value="{{ $question['help']??'' }}" maxlength="1000"></div>
    <div class="field" data-question-options><label for="question-{{ $index }}-options">Choices — one per line</label><textarea id="question-{{ $index }}-options" name="questions[{{ $index }}][options_text]" rows="4" maxlength="10000">{{ $question['options_text']??implode("\n",$question['options']??[]) }}</textarea><small>Add 2–30 different choices.</small></div>
</section>
